//! Blackout's duct-tape team marks (docs/notes/blackout.md): which arm and
//! leg surfaces are taped (`TAPED`, generated by blackout_tape_026g.py from
//! srp-026g/scripts/blackout-tape/tape.tsv's rows of method `tape`), and the
//! tape shell's model and material a taped surface gets.
//!
//! A taped record (a torso's, gloves' or legs' model and surface) gets one
//! more record: the model `ported/blackout_tape/<its base_model, '/' as
//! '_'>__<its surface>`, surface `tape`, the same part, and the material of
//! the band's colour (the item-material override: the record's material
//! buffer, 0x20545E / 0x1288C7).

#![forbid(unsafe_code)]

use core::ffi::CStr;

use crate::vostok::skin::{Band, PartKeys, PartKind, TEXT_ROOM};

/// Which part a tape row is of (tape.tsv's `slot`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum TapeSlot {
    Torso,
    Gloves,
    Legs,
}

impl TapeSlot {
    /// The part records of this slot have (the slot table 0xA79870: legs are
    /// its pants).
    pub const fn kind(self) -> PartKind {
        match self {
            TapeSlot::Torso => PartKind::Torso,
            TapeSlot::Gloves => PartKind::Gloves,
            TapeSlot::Legs => PartKind::Pants,
        }
    }
}

/// A taped surface: a slot's model and its surface (part_name).
pub struct Taped {
    pub slot: TapeSlot,
    pub base_model: &'static [u8],
    pub surface: &'static [u8],
}

include!("../../../../blackout_tape_026g.rs");

/// The shells' folder (models and materials).
const DIR: &[u8] = b"ported/blackout_tape/";
/// A shell's surface.
pub const SHELL_SURFACE: &CStr = c"tape";

/// The tape's material of a band's colour.
pub const fn material(band: Band) -> &'static CStr {
    match band {
        Band::Blue => c"ported/blackout_tape/tape_blue",
        Band::Red => c"ported/blackout_tape/tape_red",
    }
}

/// What the visual's name (its cache key) gets after it for a band: a blue
/// and a red player in the same items never share one visual.
pub const fn name_mark(band: Band) -> &'static [u8] {
    match band {
        Band::Blue => b"srpbo0_",
        Band::Red => b"srpbo1_",
    }
}

/// A shell model's name, zero-terminated, in a record's text room.
pub struct ShellModel {
    bytes: [u8; TEXT_ROOM],
}

impl ShellModel {
    /// `ported/blackout_tape/<base_model, '/' as '_'>__<surface>`; none when
    /// it and its zero do not fit a record's room (the generator refuses such
    /// a row).
    fn of(base_model: &[u8], surface: &[u8]) -> Option<ShellModel> {
        let mut bytes = [0u8; TEXT_ROOM];
        let mut at = 0;
        let parts: [&[u8]; 4] = [DIR, base_model, b"__", surface];
        for (i, part) in parts.into_iter().enumerate() {
            for &byte in part {
                // the zero after the text must fit too
                if at + 1 >= TEXT_ROOM || byte == 0 {
                    return None;
                }
                bytes[at] = if i == 1 && byte == b'/' { b'_' } else { byte };
                at += 1;
            }
        }
        Some(ShellModel { bytes })
    }

    pub fn as_cstr(&self) -> &CStr {
        // the text has no zero of its own and one after it (`of`)
        CStr::from_bytes_until_nul(&self.bytes).unwrap_or(c"")
    }
}

/// The tape row of a record, if its part, model and surface are taped.
pub fn taped(part: &PartKeys<'_>) -> Option<&'static Taped> {
    TAPED.iter().find(|row| row.slot.kind() == part.kind && row.base_model == part.base_model
        && row.surface == part.part_name)
}

/// The shell a taped record gets: its part and model.
pub fn shell_of(part: &PartKeys<'_>) -> Option<(PartKind, ShellModel)> {
    let row = taped(part)?;
    Some((row.slot.kind(), ShellModel::of(row.base_model, row.surface)?))
}

#[cfg(test)]
mod tests {
    use super::*;

    fn keys<'a>(kind: PartKind, base_model: &'a [u8], part_name: &'a [u8]) -> PartKeys<'a> {
        PartKeys { kind, base_model, part_name }
    }

    #[test]
    fn every_row_has_a_shell() {
        assert!(!TAPED.is_empty());
        for row in &TAPED {
            let (kind, shell) = shell_of(&keys(row.slot.kind(), row.base_model, row.surface)).expect("a shell");
            assert_eq!(kind, row.slot.kind());
            let name = shell.as_cstr().to_bytes();
            assert!(name.starts_with(DIR) && name.ends_with(row.surface));
            assert!(!name[DIR.len()..].contains(&b'/'));
            assert!(name.len() < TEXT_ROOM);
        }
    }

    #[test]
    fn the_shell_name() {
        let shell = ShellModel::of(b"character/human/base/base_character_torso_s1", b"base_character_torso_s").unwrap();
        assert_eq!(
            shell.as_cstr(),
            c"ported/blackout_tape/character_human_base_base_character_torso_s1__base_character_torso_s"
        );
        // the surface keeps its own characters; only the model's '/' become '_'
        assert_eq!(ShellModel::of(b"a/b", b"c/d").unwrap().as_cstr(), c"ported/blackout_tape/a_b__c/d");
        let long = [b'x'; TEXT_ROOM];
        assert!(ShellModel::of(&long, b"s").is_none());
        let just = [b'x'; TEXT_ROOM - 1 - 21 - 2 - 1];
        assert_eq!(ShellModel::of(&just, b"s").unwrap().as_cstr().to_bytes().len(), TEXT_ROOM - 1);
        assert!(ShellModel::of(&[b'x'; TEXT_ROOM - 21 - 2 - 1], b"s").is_none());
        assert!(ShellModel::of(b"a\0b", b"s").is_none());
    }

    #[test]
    fn a_row_matches_its_part_model_and_surface_only() {
        let row = &TAPED[0];
        let kind = row.slot.kind();
        assert!(taped(&keys(kind, row.base_model, row.surface)).is_some());
        let other = if kind == PartKind::Torso { PartKind::Boots } else { PartKind::Torso };
        assert!(taped(&keys(other, row.base_model, row.surface)).is_none());
        assert!(taped(&keys(kind, row.base_model, b"another_surface")).is_none());
        assert!(taped(&keys(kind, b"character/human/unknown", row.surface)).is_none());
        assert!(taped(&keys(PartKind::Head, row.base_model, row.surface)).is_none());
    }

    #[test]
    fn slots_are_their_parts() {
        assert_eq!(TapeSlot::Gloves.kind(), PartKind::Gloves);
        assert_eq!(TapeSlot::Torso.kind(), PartKind::Torso);
        assert_eq!(TapeSlot::Legs.kind(), PartKind::Pants);
        assert_eq!(material(Band::Blue), c"ported/blackout_tape/tape_blue");
        assert_eq!(material(Band::Red), c"ported/blackout_tape/tape_red");
        assert_ne!(name_mark(Band::Blue), name_mark(Band::Red));
    }
}
